import unittest

from slugkit import normalize_version, slugify


class SlugifyTests(unittest.TestCase):
    def test_slugify(self):
        self.assertEqual(slugify("  Hello, World! "), "hello-world")

    def test_repeated_punctuation_collapses_to_one_separator(self):
        self.assertEqual(slugify("Hello,,,   World!!!"), "hello-world")
        self.assertEqual(slugify("a--b__c"), "a-b-c")

    def test_leading_and_trailing_separators_are_stripped(self):
        self.assertEqual(slugify("--Foo Bar--"), "foo-bar")

    def test_empty_and_punctuation_only_input(self):
        self.assertEqual(slugify(""), "")
        self.assertEqual(slugify("!!! ???"), "")

    def test_unicode_letters_are_dropped_known_limitation(self):
        # Documented limitation (see CHANGELOG): no transliteration in 0.4.0.
        self.assertEqual(slugify("café"), "caf")


class NormalizeVersionTests(unittest.TestCase):
    ORDINARY_VERSIONS = (
        "0.1",
        "0.4.0",
        "1.2.0",
        "1.2.3.4",
        "2024.10.1",
        "1.0.0.post1",
    )

    PRE_RELEASE_VERSIONS = (
        "2.0rc1",
        "1.0b2",
        "1.0a1",
        "1.0.0rc2",
        "1.0RC1",
    )

    def test_ordinary_versions_are_returned_unchanged(self):
        # Matches str(distutils.version.LooseVersion(v)) for these inputs.
        for text in self.ORDINARY_VERSIONS:
            with self.subTest(version=text):
                self.assertEqual(normalize_version(text), text)

    def test_pre_release_suffixes_are_preserved(self):
        for text in self.PRE_RELEASE_VERSIONS:
            with self.subTest(version=text):
                self.assertEqual(normalize_version(text), text)

    def test_whitespace_padded_input_is_returned_verbatim(self):
        # LooseVersion never stripped whitespace; that behavior is retained.
        self.assertEqual(normalize_version(" 1.2.0 "), " 1.2.0 ")

    def test_strings_without_components_raise_value_error(self):
        for text in ("", "   ", "...", "!!!", "-._"):
            with self.subTest(version=text):
                with self.assertRaises(ValueError):
                    normalize_version(text)

    def test_non_string_input_raises_type_error(self):
        for bad in (1.2, None, (1, 2)):
            with self.subTest(value=bad):
                with self.assertRaises(TypeError):
                    normalize_version(bad)


if __name__ == "__main__":
    unittest.main()

