import re
from slugkit import normalize_version

# Verbatim replica of distutils.version.LooseVersion parse/__str__ (CPython source).
class LooseVersion:
    component_re = re.compile(r'(\d+ | [a-z]+ | \.)', re.VERBOSE)
    def __init__(self, vstring=None):
        if vstring:
            self.parse(vstring)
    def parse(self, vstring):
        self.vstring = vstring
        components = [x for x in self.component_re.split(vstring) if x and x != '.']
        for i, obj in enumerate(components):
            try:
                components[i] = int(obj)
            except ValueError:
                pass
        self.version = components
    def __str__(self):
        return self.vstring

corpus = [
    "0.1", "0.4.0", "1.2.0", "1.2.3.4", "2024.10.1", "1.0.0.post1",
    "2.0rc1", "1.0b2", "1.0a1", "1.0.0rc2", "1.0RC1", " 1.2.0 ",
    "1.0-beta", "3!1.0", "1.0.dev3", "v1.2", "0.0.0.0", "99999999999999999999.1",
]
mismatch = 0
for v in corpus:
    old, new = str(LooseVersion(v)), normalize_version(v)
    status = "OK " if old == new else "DIFF"
    if old != new: mismatch += 1
    print(f"{status} {v!r:28} LooseVersion={old!r:28} normalize_version={new!r}")
print(f"\n{len(corpus)} inputs, {mismatch} mismatches")

# Degenerate inputs: documented deviations
for v in ("", "...", "!!!", "-._"):
    try:
        LooseVersion(v) and str(LooseVersion(v))
        old = repr(str(LooseVersion(v)))
    except AttributeError as e:
        old = f"AttributeError({e})"
    try:
        new = repr(normalize_version(v))
    except ValueError as e:
        new = f"ValueError({e})"
    print(f"degenerate {v!r:8} old={old:60} new={new}")
EOF

